    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        names = sorted(packages, reverse=(name_order == "descending"))
        best = None
        best_versions = None

        def acyclic(edges):
            done, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, ())):
                    return False
                active.remove(name)
                done.add(name)
                return True
            return all(visit(name) for name in edges)

        def search(assigned, edges, pending):
            nonlocal best, best_versions
            if not pending:
                if not acyclic(edges):
                    return
                key = tuple(assigned.get(name, -1) for name in names)
                better = best is None or (key < best if preference == "minimum" else key > best)
                if better:
                    best, best_versions = key, dict(assigned)
                return

            name, low, high, parent = pending[-1]
            rest = pending[:-1]
            new_edges = {n: set(v) for n, v in edges.items()}
            if parent is not None:
                new_edges.setdefault(parent, set()).add(name)
            if name in assigned:
                version = assigned[name]
                if low <= version <= high:
                    search(assigned, new_edges, rest)
                return

            rows = [row for row in packages.get(name, [])
                    if low <= row["version"] <= high
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            rows.sort(key=lambda row: row["version"], reverse=(preference == "maximum"))
            for row in rows:
                versions = dict(assigned)
                versions[name] = row["version"]
                next_edges = {n: set(v) for n, v in new_edges.items()}
                next_edges.setdefault(name, set())
                deps = [dep for dep in row.get("deps", [])
                        if not dep.get("feature") or dep["feature"] in features]
                next_pending = list(rest)
                next_pending.extend((dep["name"], dep["min"], dep["max"], name)
                                    for dep in deps)
                search(versions, next_edges, next_pending)

        pending = [(name, bounds[0], bounds[1], None)
                   for name, bounds in data["roots"].items()]
        search({}, {}, pending)
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        winners = {}
        cutoff = data.get("cutoff", 10**9)
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (sequence, event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    from itertools import combinations

    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for subset in combinations(jobs, k):
            ids = [job["id"] for job in subset]
            id_set = set(ids)
            if not mandatory.issubset(id_set):
                continue
            counts = {}
            valid = True
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            for group, (low, high) in quotas.items():
                count = counts.get(group, 0)
                if not low <= count <= high:
                    valid = False
                    break
            if not valid:
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"]
                   for i in range(len(ordered) - 1)):
                continue
            value = sum(job["value"] for job in subset)
            selected = sorted(ids)
            if (best_value is None or value > best_value
                    or (value == best_value and selected < best_ids)):
                best_value, best_ids = value, selected
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit_for.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], data["coupons"], initial_mask)
        distance = {start_state: data["start"]}
        queue = [(data["start"], data["source"], data["coupons"], initial_mask)]
        while queue:
            time, node, remaining, mask = heapq.heappop(queue)
            state = (node, remaining, mask)
            if distance.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                for used in (0, 1):
                    if used and remaining == 0:
                        continue
                    duration = edge["duration"]
                    if used:
                        duration = max(2, duration - edge.get("discount", 0))
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_remaining = remaining - used
                    next_mask = mask | bit_for.get(nxt, 0)
                    next_state = (nxt, next_remaining, next_mask)
                    if arrival < distance.get(next_state, float("inf")):
                        distance[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, next_remaining, next_mask))
        return {"arrival": None}
    return solve


